  const keysArray = Object.keys(jsonObj);

  // Sort the array of keys using the default alphabetical order
  const sortedKeysArray = keysArray.sort();

  // Use reduce() method to create a new JSON object with sorted keys and their corresponding values
  return sortedKeysArray.reduce((result, key) => {
    result[key] = jsonObj[key];
