import django.db as db

CONFIG = 'model1'  # Change this to switch between models

class DynamicModel(type):
    def __new__(mcs, name, bases, attrs):
        model = super().__new__(mcs, name, bases, attrs)

        if CONFIG == 'model1':
            model.Meta.db_table = 'tablename1'
            model._meta.fields += (
                'column_x', models.CharField(max_length=255),
