```csharp using System;
using System.Net.Http;
using System.Threading.Tasks;

public class RestServiceWrapper
{
    private readonly HttpClient _httpClient;
    private string _accessToken;

    public RestServiceWrapper(string baseAddress)
    {
        _httpClient = new HttpClient { BaseAddress = new Uri(baseAddress) };
    }

    // Setter for access token
    public void SetAccessToken(string token)
    {
        _accessToken = token;
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _accessToken);
    }

    // Method for getting data from an API endpoint
    public async Task<HttpResponseMessage> GetAsync(string requestUri)
    {
        return await _httpClient.GetAsync(requestUri);
    }

    // Method for sending a POST request with JSON body
    public async Task<HttpResponseMessage> PostJsonAsync<T>(string requestUri, T jsonBody) where T : new()
    {
        var content = new StringContent(Newtonsoft.Json.JsonConvert.SerializeObject(jsonBody), System.Text.Encoding.UTF8, "application/json");
        return await _httpClient.PostAsync(requestUri, content);
    }
}
```

To use this wrapper class, first initialize it with your REST API base address:

```csharp
