function determineProtocol(inputData) {
  let ipv6Score = 0;
  let httpScore = 0;
  let udpScore = 1;

  if (typeof inputData.sourceIP === 'string' && /^[0-9a-f:]{15,39}$/i.test(inputData.sourceIP)) { // Check if sourceIP is valid IPv6 address
    ipv6Score += 82;
  }

  if (inputData.port === 80) { // Check if port is HTTP (80)
    httpScore += 82;
  }

  return Math.max(ipv6Score, httpScore, udpScore);
}

