 Here's an example of creating a professional access permissions guard using middleware in Nest.js with TypeORM for handling user roles and their associated permissions:

```javascript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { JwtAuthGuard } from '@auth0/passport-jwt';
import { Reflector } from '@nestjs/core';
import { Role } from './role.enum';
import { PermissionsRepository } from './permissions.repository';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(
    private reflector: Reflector,
    private permissionsRepository: PermissionsRepository,
  ) {}

  canActivate(context: ExecutionContext): boolean {
    const roles = this.reflector.get<Role[]>('roles', context.getHandler());
    if (!roles) {
      return true; // If no roles are specified, allow access
    }

    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (!user || !user.role) {
      throw new UnauthorizedException('Unauthenticated or invalid role');
    }

    const requiredRoles = (roles as Role[]).filter((r) => r !== 'all'); // Exclude 'all' role if present
    const userPermissions = this.permissionsRepository.findUserPermissions(user.id);

    return requiredRoles.every((requiredRole) =>
      userPermissions.some((permission) => permission.role === requiredRole),
    );
  }
}
```

