 Here's an example of a simple decorator for Nest.js middleware that checks the `NODE_ENV` environment variable and calls the `next()` function if it's set to `true`, or returns `false` otherwise:

```typescript
import { CreateContextDecoder, ExecutionContext, Injectable, NestMiddleware } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';

@Injectable()
export class EnvCheckerMiddleware implements NestMiddleware {
  use(req: Request, res: Response, next: NextFunction, @CreateContextDecoder() ctx: ExecutionContext) {
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      next();
    } else {
      res.status(403).send(false);
    }
  }
}

// Decorate your controller method with this decorator to apply the middleware
export function CheckNodeEnvDecorator(): MethodDecorator {
  return (target: Object, key: string, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: any[]) {
      const req = args[0] as Request;
      const res = args[1] as Response;
      const next = args[2] as NextFunction;
      await new Promise((resolve) => {
        req.app.get('middlewareConsumerInstance').runMiddleware(new EnvCheckerMiddleware(), req, res, next, () => {
          if (res.sent) {
            return;
          }
          originalMethod.apply(this, args);
          resolve();
        });
      });
    };

    return descriptor;
  };
}
```

This decorator can be applied to any controller method in your application by using the `@CheckNodeEnvDecorator()` decorator before the method definition:

