 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Create a slice of specific negative words.
2. Tokenize the given sentence into words.
3. Iterate through each token (word) in the sentence.
4. Check if the current token is one of the negative words or the phrase "not" followed by a negative word.
5. If the condition is met, mark that token as negative.
6. After iterating through all tokens, check if there is more than one marked negative token.
7. If there are more than one negative tokens, print a message indicating that the sentence contains a double negative.

Here's an example implementation in Go:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"isn't", "am not", "doesn't", "does not", "had not", "hasn't", "haven't", "is not", "aren't", "aren't not", "wasn't", "was not", "hadn't been", "have not been", "has not been", "had not been been", "had not been not"}
	sentence := "He isn't not worried about the coronavirus situation"

	tokens := strings.Split(sentence, " ")
	numNegatives := 0

	for _, token := range tokens {
		if containsNegation(token) {
			numNegatives++
		}
	}

	if numNegatives > 1 {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func containsNegation(token string) bool {
	for _, negativeWord := range negativeWords {
		if strings.HasPrefix(token, negativeWord) || strings.Contains(token, negativeWord[len(negativeWord)-3:]) {
			return true
		}
	}
	return false
}
```

